// 一時ファイルに書いて、読み戻す(最後に削除する)
// ここを変えてみよう:書く文字列を変える / APPEND を外して上書きにしてみる
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;   // Path, Files, StandardOpenOption
import java.util.List;

public class WriteRead {
    public static void main(String[] args) throws IOException {
        Path tmp = Files.createTempFile("memo", ".txt");
        Files.writeString(tmp, "1行目:こんにちは\n",
                StandardCharsets.UTF_8);
        Files.writeString(tmp, "2行目:Java\n",
                StandardCharsets.UTF_8,
                StandardOpenOption.APPEND);   // 追記モード

        System.out.println("存在する?: " + Files.exists(tmp));
        // 日本語は UTF-8 だと1文字3バイト
        System.out.println("バイト数: " + Files.size(tmp));

        System.out.println("--- readString ---");
        System.out.print(Files.readString(tmp));

        System.out.println("--- readAllLines ---");
        List<String> lines = Files.readAllLines(tmp);
        for (int i = 0; i < lines.size(); i++) {
            String s = lines.get(i);
            System.out.println((i + 1) + ": " + s
                    + "(" + s.length() + "文字)");
        }

        Files.delete(tmp);                    // 後片付け
        System.out.println("削除後に存在する?: "
                + Files.exists(tmp));
    }
}

// ログファイルから ERROR 行を数える
// ここを変えてみよう:"[ERROR]" を "ERROR" にすると件数は?
import java.io.*;         // IOException, BufferedReader
import java.nio.file.*;   // Path, Files
import java.util.List;
import java.util.stream.Stream;

public class ErrorCount {
    public static void main(String[] args) throws IOException {
        Path log = Files.createTempFile("app", ".log");
        Files.write(log, List.of(
                "09:00:01 [INFO] 起動しました",
                "09:00:05 [ERROR] DB接続に失敗",
                "09:00:06 [WARN] ERROR率が上昇中",
                "09:00:09 [ERROR] タイムアウト"));

        // Files.lines は try-with-resources で必ず閉じる
        long errors;
        try (Stream<String> s = Files.lines(log)) {
            errors = s.filter(l -> l.contains("[ERROR]"))
                      .count();
        }
        System.out.println("ERROR 行: " + errors + " 件");

        // 1行ずつ読む昔ながらの書き方(巨大ファイル向き)
        try (BufferedReader r = Files.newBufferedReader(log)) {
            String line;
            int no = 0;
            while ((line = r.readLine()) != null) { // 終端で null
                no++;
                if (line.contains("[ERROR]")) {
                    System.out.println(no + "行目: " + line);
                }
            }
        }
        Files.delete(log);              // 閉じてあるので消せる
    }
}

// 売上CSVを店舗別に集計して、別フォルダのファイルに書き出す
// ここを変えてみよう:データ行を足す / 空行チェックを消すとどうなる?
import java.io.*;         // IOException, BufferedReader/Writer
import java.nio.file.*;   // Path, Files
import java.util.*;       // List, Map, TreeMap

public class SalesSummary {
    public static void main(String[] args) throws IOException {
        Path dir = Files.createTempDirectory("sales");
        Path in = dir.resolve("sales.csv");
        Files.write(in, List.of(
                "日付,店舗,金額",
                "2026-10-01,渋谷,1200",
                "2026-10-01,新宿,800",
                "",
                "2026-10-02,渋谷,500"));

        Map<String, Integer> total = new TreeMap<>();
        try (BufferedReader r = Files.newBufferedReader(in)) {
            r.readLine();                   // ヘッダーを読み捨てる
            String line;
            while ((line = r.readLine()) != null) {
                if (line.isBlank()) {
                    continue;               // 空行は飛ばす
                }
                String[] c = line.split(","); // 日付,店舗,金額
                total.merge(c[1], Integer.parseInt(c[2]),
                        Integer::sum);
            }
        }

        Path out = dir.resolve("report/summary.csv");
        Files.createDirectories(out.getParent()); // report を作る
        try (BufferedWriter w = Files.newBufferedWriter(out)) {
            w.write("店舗,合計");
            w.newLine();
            for (String shop : total.keySet()) {
                w.write(shop + "," + total.get(shop));
                w.newLine();
            }
        }
        System.out.print(Files.readString(out));

        // 後片付け(フォルダは中身を消してから)
        Files.delete(out);
        Files.delete(out.getParent());
        Files.delete(in);
        Files.delete(dir);
    }
}

// Excel が保存した CSV(MS932)を UTF-8 / MS932 で読む
